function readConfig(name, callback) {
  if (name === "") {
    throw new Error("no name");
  }
  setTimeout(() => callback(null, name + ".json"), 0);
}

for (const name of ["app", ""]) {
  try {
    readConfig(name, (error, file) => console.log("read " + file));
    console.log("asked for " + name);
  } catch (error) {
    console.log("caught " + error.message);
  }
}
